#define N 1024
int matrix[N][N];

// Good Spatial Locality (Row Major)
void access_good() {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            matrix[i][j]++; // Contiguous access
        }
    }
}

// Poor Spatial Locality (Column Major)
void access_bad() {
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            matrix[i][j]++; // Large memory jump
        }
    }
}

#define CACHE_LINE_SIZE 64

// False Sharing Avoidance (Manual Padding)
struct AlignedCounter {
    // Data modified by Thread A
    int threadA_count;
    // Pad ensures threadB_count is on a different cache line
    char padding[CACHE_LINE_SIZE - sizeof(int)];
    // Data modified by Thread B
    int threadB_count;
};

// Temporal Locality Example
// Data elements are accessed repeatedly (high reuse)
int sum_local(int* arr, int size) {
    int sum = 0;
    for (int i = 0; i < size; ++i) {
        int temp = arr[i];
        sum += temp;
        sum *= temp; // arr[i] reused before eviction
    }
    return sum;
}

// GCC/Clang Cache Alignment Pragma
struct __attribute__((aligned(64))) CacheAlignedData {
    int data[10]; // Structure guaranteed to start on a cache line boundary
};
